/// Calls `vspa_validation_bytes` of the Vesper library `serde` (`vesper_serde_vspa_validation_bytes`).
pub fn vspa_validation_bytes(count: u64) -> Result<u64, crate::port_types::BinError> {
    let mut fail = [0u64; 3];
    // SAFETY: `vesper_serde_vspa_validation_bytes` has exactly this signature in the export ABI; every
    // pointer is a live, writable buffer of the size the ABI requires, and
    // every handle passed is owned or borrowed as its mode requires.
    let raw = unsafe { vesper_serde_vspa_validation_bytes(count as i64, fail.as_mut_ptr()) };
    match fail[0] {
        0 => Ok(raw as u64),
        1 => Err(<crate::port_types::BinError as Abi>::get(&fail[1..])),
        status => panic!("invalid failure status {status} from vesper_serde_vspa_validation_bytes"),
    }
}

